//! String table. One row per key: en, ja, es, de, fr, ko, ru, tr, kk.
//! Placeholders are `{0}`, `{1}` (see `fmt`).

macro_rules! strings {
    ($($k:ident => [$en:expr, $ja:expr, $es:expr, $de:expr, $fr:expr, $ko:expr, $ru:expr, $tr:expr, $kk:expr];)*) => {
        /// String identifiers. Add keys here; never format user text elsewhere.
        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
        pub enum Key {
            $($k,)*
        }

        impl Key {
            /// Every key, in declaration order.
            pub const ALL: &'static [Key] = &[$(Key::$k,)*];
        }

        /// Rows indexed by `Key as usize`; columns follow `Lang::ALL`.
        pub(crate) static TABLE: &[[&str; 9]] = &[$([$en, $ja, $es, $de, $fr, $ko, $ru, $tr, $kk],)*];
    };
}

